script:
function decideAction(changed,valid){
 if(changed)return {title:'写入新内容，使旧缓存失效',detail:'内容已经变化，当前缓存不能继续代表新内容。'};
 if(valid)return {title:'跳过写入，复用缓存',detail:'内容未变化，且缓存有效，可使用已有结果。'};
 return {title:'跳过写入，重新计算',detail:'内容未变化，但缓存已无效，不能继续复用。'};
}
const changed=document.getElementById('changed'),valid=document.getElementById('valid');
function updateResult(){const result=decideAction(changed.checked,valid.checked);document.getElementById('result-title').textContent=result.title;document.getElementById('result-detail').textContent=result.detail;}
changed.addEventListener('change',updateResult);valid.addEventListener('change',updateResult);
